package gen

import (
	"fmt"
	"go/format"
	"os"
	"path/filepath"
	"strings"
)

// Options configures a generation run. See genpb.Options for documentation;
// this is the same set of knobs with Only already split.
type Options struct {
	Dir        string
	Tag        string
	Out        string
	Only       []string
	StampStock bool
	Runtime    bool
}

// RuntimePkg is the import path of the support package generated files use
// when Options.Runtime is set.
const RuntimePkg = "github.com/soypat/embedpb/pbruntime"

// Run loads dir's stock *.pb.go and writes the reflection-free companion.
func Run(opts Options) error {
	if opts.Dir == "" {
		opts.Dir = "."
	}
	if opts.Tag == "" && opts.StampStock {
		return fmt.Errorf("StampStock needs a Tag to negate")
	}
	var only map[string]bool
	if len(opts.Only) > 0 {
		only = map[string]bool{}
		for _, n := range opts.Only {
			only[strings.TrimSpace(n)] = true
		}
	}
	pkg, err := load(opts.Dir, only)
	if err != nil {
		return err
	}

	src := render(pkg, opts)
	formatted, ferr := format.Source([]byte(src))
	if ferr != nil {
		// Write unformatted for debugging, then report.
		_ = os.WriteFile(filepath.Join(opts.Dir, "embedpb_generated.go.raw"), []byte(src), 0o644)
		return fmt.Errorf("gofmt failed (raw dumped): %w", ferr)
	}

	out := opts.Out
	if out == "" {
		out = filepath.Join(opts.Dir, "embedpb_generated.go")
	}
	if err := os.WriteFile(out, formatted, 0o644); err != nil {
		return err
	}
	fmt.Printf("embedpb: wrote %s (%d messages, %d enums)\n", out, len(pkg.Messages), len(pkg.Enums))

	if opts.StampStock {
		if err := stampStock(opts.Dir, opts.Tag); err != nil {
			return fmt.Errorf("stamp stock: %w", err)
		}
	}
	return nil
}

type w struct{ b strings.Builder }

func (x *w) p(format string, a ...any) { fmt.Fprintf(&x.b, format+"\n", a...) }

func render(pkg *Package, opts Options) string {
	x := &w{}
	if opts.Tag != "" {
		x.p("//go:build %s", opts.Tag)
		x.p("")
	}
	x.p("// Code generated by embedpb. DO NOT EDIT.")
	x.p("// Reflection-free, TinyGo-safe proto codec: hand-written protoiface.Methods")
	x.p("// keep google.golang.org/protobuf on its fast path (no reflect coder).")
	x.p("package %s", pkg.Name)
	x.p("")
	needTime := false
	for _, e := range pkg.Externals {
		if e.Ref == "timestamppb.Timestamp" {
			needTime = true
		}
	}
	x.p("import (")
	x.p("\t\"bytes\"")
	x.p("\t\"encoding/base64\"")
	x.p("\t\"fmt\"")
	x.p("\t\"math\"")
	x.p("\t\"sort\"")
	x.p("\t\"strconv\"")
	if needTime {
		x.p("\t\"time\"")
	}
	x.p("")
	x.p("\t\"google.golang.org/protobuf/encoding/protowire\"")
	x.p("\t\"google.golang.org/protobuf/reflect/protoreflect\"")
	if !opts.Runtime {
		x.p("\t\"google.golang.org/protobuf/runtime/protoiface\"")
	} else {
		x.p("\t%q", RuntimePkg)
	}
	for _, im := range pkg.Imports {
		x.p("\t%s %q", im.Name, im.Path)
	}
	x.p(")")
	x.p("")
	x.p("var _ = math.Float32bits")
	x.p("var _ = sort.Strings")
	x.p("var _ = fmt.Sprintf")
	x.p("var _ = bytes.Equal")
	x.p("var _ = strconv.AppendInt")
	x.p("var _ = base64.StdEncoding")
	if needTime {
		x.p("var _ = time.Unix")
	}
	x.p("")

	for _, e := range pkg.Enums {
		renderEnum(x, e)
	}
	for _, o := range pkg.Oneofs {
		renderOneofTypes(x, o)
	}
	for _, m := range pkg.Messages {
		renderMessage(x, m)
	}
	renderExternals(x, pkg.Externals)
	renderShim(x, opts.Runtime)
	return x.b.String()
}

func renderEnum(x *w, e Enum) {
	x.p("type %s int32", e.GoName)
	x.p("const (")
	for _, v := range e.Vals {
		x.p("\t%s %s = %d", v.GoName, e.GoName, v.Num)
	}
	x.p(")")
	x.p("var %s_name = map[int32]string{", e.GoName)
	seenNum := map[int32]bool{}
	for _, v := range e.Vals {
		if seenNum[v.Num] {
			continue // enum alias: keep first proto name only
		}
		seenNum[v.Num] = true
		x.p("\t%d: %q,", v.Num, v.ProtoName)
	}
	x.p("}")
	x.p("func (x %s) String() string {", e.GoName)
	x.p("\tif s, ok := %s_name[int32(x)]; ok { return s }", e.GoName)
	x.p("\treturn fmt.Sprintf(\"%s(%%d)\", int32(x))", e.GoName)
	x.p("}")
	x.p("func (x %s) Enum() *%s { p := new(%s); *p = x; return p }", e.GoName, e.GoName, e.GoName)
	x.p("")
}

func renderOneofTypes(x *w, o Oneof) {
	x.p("type %s interface{ %s() }", o.IfaceGo, o.IfaceGo)
	for _, c := range o.Cases {
		x.p("type %s struct{ %s %s }", c.WrapperGo, c.FieldGo, oneofFieldGoType(c.Elem))
		x.p("func (*%s) %s() {}", c.WrapperGo, o.IfaceGo)
	}
	x.p("")
}

func renderMessage(x *w, m Message) {
	// struct
	x.p("type %s struct {", m.GoName)
	for _, f := range m.Fields {
		if f.Oneof != nil {
			x.p("\t%s %s", f.Oneof.GoName, f.Oneof.IfaceGo)
			continue
		}
		x.p("\t%s %s", f.GoName, fieldGoType(f))
	}
	x.p("\tunknownFields protoreflect.RawFields")
	x.p("}")
	x.p("")
	x.p("func (m *%s) Reset() { *m = %s{} }", m.GoName, m.GoName)
	x.p("func (m *%s) String() string { return fmt.Sprintf(\"%s{}\") }", m.GoName, m.GoName)
	x.p("func (m *%s) ProtoMessage() {}", m.GoName)

	// getters
	renderGetters(x, m)

	// ProtoReflect
	x.p("func (m *%s) ProtoReflect() protoreflect.Message {", m.GoName)
	x.p("\treturn msgReflect{MarshalFn: m.marshalAppend, SizeFn: m.sizeField, UnmarshalFn: m.unmarshalMsg, Iface: m, Valid: m != nil,")
	x.p("\t\tNewFn: func() protoreflect.Message { return (&%s{}).ProtoReflect() },", m.GoName)
	x.p("\t\tGetUnknownFn: func() protoreflect.RawFields { return m.unknownFields },")
	x.p("\t\tSetUnknownFn: func(f protoreflect.RawFields) { m.unknownFields = f }}")
	x.p("}")
	x.p("")

	renderSize(x, m)
	renderMarshal(x, m)
	renderUnmarshal(x, m)
	renderJSON(x, m)
}

func renderGetters(x *w, m Message) {
	recv := "m"
	for _, f := range m.Fields {
		if f.Oneof != nil {
			o := f.Oneof
			x.p("func (%s *%s) Get%s() %s { if %s != nil { return %s.%s }; return nil }", recv, m.GoName, o.GoName, o.IfaceGo, recv, recv, o.GoName)
			for _, c := range o.Cases {
				gt := oneofFieldGoType(c.Elem)
				x.p("func (%s *%s) Get%s() %s {", recv, m.GoName, c.FieldGo, gt)
				x.p("\tif v, ok := %s.Get%s().(*%s); ok { return v.%s }", recv, o.GoName, c.WrapperGo, c.FieldGo)
				x.p("\treturn %s", zeroLit(c.Elem))
				x.p("}")
			}
			continue
		}
		gt := fieldGoType(f)
		switch f.Card {
		case CardOptional:
			if f.Elem.Kind == "bytes" {
				x.p("func (%s *%s) Get%s() []byte { if %s != nil { return %s.%s }; return nil }", recv, m.GoName, f.GoName, recv, recv, f.GoName)
			} else if f.Elem.Kind == "message" {
				x.p("func (%s *%s) Get%s() %s { if %s != nil { return %s.%s }; return nil }", recv, m.GoName, f.GoName, gt, recv, recv, f.GoName)
			} else {
				base := scalarGoType(f.Elem)
				x.p("func (%s *%s) Get%s() %s { if %s != nil && %s.%s != nil { return *%s.%s }; return %s }", recv, m.GoName, f.GoName, base, recv, recv, f.GoName, recv, f.GoName, zeroLit(f.Elem))
			}
		case CardRepeated, CardMap:
			x.p("func (%s *%s) Get%s() %s { if %s != nil { return %s.%s }; return nil }", recv, m.GoName, f.GoName, gt, recv, recv, f.GoName)
		default:
			if f.Elem.Kind == "message" {
				x.p("func (%s *%s) Get%s() %s { if %s != nil { return %s.%s }; return nil }", recv, m.GoName, f.GoName, gt, recv, recv, f.GoName)
			} else {
				x.p("func (%s *%s) Get%s() %s { if %s != nil { return %s.%s }; return %s }", recv, m.GoName, f.GoName, gt, recv, recv, f.GoName, zeroLit(f.Elem))
			}
		}
	}
	x.p("")
}
